# -*- coding: utf-8 -*-
from common import *
from content import DESCRIPTIONS
from catalog import TOOLS,GROUPS
import zipfile

def tools_page(lang):
    t=lambda en,zh:pick(lang,en,zh)
    body=hero(lang,'tools',t('Choose the right source<br><em>Inspect its scope</em>','选择适用来源<br><em>检查适用范围</em>'),t('A searchable directory of '+str(len(TOOLS))+' primary resources and original tools. Normative standards, expired drafts and implementation documentation have different authority.','可搜索的 '+str(len(TOOLS))+' 项一手资源及原始工具。规范标准、过期草案和实现文档具有不同权威范围。'))+'<div class="reading wrap"><section class="chapter-section">'
    body+='<div class="tool-filter"><label for="tool-search">'+t('Search name, use or limitation','搜索名称、用途或限制')+'</label><input type="search" id="tool-search" placeholder="'+t('e.g. SM2, SHA-3, AES, OpenSSL','例如 SM2、SHA-3、AES、OpenSSL')+'"><label for="tool-category">'+t('Category','类别')+'</label><select id="tool-category"><option value="all">'+t('All categories','所有类别')+'</option>'+''.join(f'<option value="{k}">{v[1 if lang=="zh" else 0]}</option>' for k,v in GROUPS.items())+'</select><p id="tool-count" role="status" aria-live="polite">'+t(str(len(TOOLS))+' resources',str(len(TOOLS))+' 项资源')+'</p></div><div class="tool-grid">'
    for ident,name,url,group,en,zh,limen,limzh in TOOLS:body+=f'<article class="tool-card" data-category="{group}"><span class="eyebrow">{GROUPS[group][1 if lang=="zh" else 0]}</span><h3>{escape(name)}</h3><p>{t(en,zh)}</p><small>{t(limen,limzh)}</small><a href="{url}" target="_blank" rel="noopener noreferrer">'+t('Open original resource ↗','打开原始资源 ↗')+'</a></article>'
    return body+'</div><p id="tool-empty" hidden>'+t('No matching resources. Try another word or category.','无匹配资源，请尝试其他词或类别。')+'</p></section>'+callout(t('Check standard and implementation versions','检查标准及实现版本'),t('Public reference code helps inspect transformations. Standards and library builds determine exact interfaces; a known-answer test is not a product certificate.','公开参考代码便于观察变换；标准和库构建决定精确接口，已知答案测试不是产品认证。'))+'</div>'

def sources_page(lang):
    t=lambda en,zh:pick(lang,en,zh)
    body=hero(lang,'sources',t('Read primary documents<br><em>Compare the assumptions</em>','阅读一手文档<br><em>比较假设</em>'),t('Algorithm texts, NIST comparisons, protocol profiles and original implementors. Each source has a scope/status note; chapters link to the relevant originals.','算法文本、NIST 对比、协议配置及原始实现；每项来源说明范围 / 状态，章节链接到相关原文。'))+'<div class="reading wrap">'
    for i,(group,(en,zh)) in enumerate(GROUPS.items(),1):
        grid='<div class="source-grid">'+''.join(f'<a class="source-card" href="{url}" target="_blank" rel="noopener noreferrer"><span class="eyebrow">{t("ORIGINAL PUBLISHER","原始发布者")}</span><h3>{escape(name)} ↗</h3><p>{t(limen,limzh)}</p></a>' for ident,name,url,g,enq,zhq,limen,limzh in TOOLS if g==group)+'</div>'
        body+=section(f'{i:02} / SOURCES',t(en,zh),t('Read the lesson, then inspect the exact standard, version and encoding.','先阅读章节，再检查精确标准、版本及编码。'),grid,group)
    body+=callout(t('A reading route when full text is inconvenient','全文不便访问时的阅读路径'),t('Official GB metadata identifies the normative text and status. English explanatory drafts and upstream implementations are secondary reading routes within this primary-source collection; expired drafts are clearly labelled and are not presented as current standards. GSMA and NXP can reject automated or network-specific requests; ZUC also has an independent official 3GPP archive entry.','官方 GB 元数据标识规范文本及状态。英文解释性草案和上游实现是本一手来源集中的补充阅读路径；过期草案明确标注，不能视为现行标准。GSMA 与 NXP 可能拒绝自动或特定网络的请求；ZUC 另提供 3GPP 官方归档入口。'))
    return body+'</div>'


def overview(lang):
    t=lambda en,zh:pick(lang,en,zh)
    parts=[('01','SM2',t('Identity, ECC and three distinct schemes','身份、ECC 与三种不同方案')),('02','SM3',t('Compression versus SHA-2 / SHA-3','压缩与 SHA-2 / SHA-3')),('03','SM4',t('Word rounds versus AES byte state','字轮与 AES 字节状态')),('04',t('IMPLEMENTATION','实现'),t('Exact bytes, real checks and engineering scope','精确字节、真实检查及工程范围'))]
    graphic='<aside class="trust-map" aria-label="'+t('Four paths into GM algorithms','国密算法的四条学习路径')+'"><div class="map-label">IDENTITY / WORDS / STATE / EVIDENCE</div>'+''.join(f'<div class="map-step"><span>{n}</span><div><strong>{title}</strong><small>{desc}</small></div></div>' for n,title,desc in parts)+'<div class="map-foot">'+t('Compare the same layer before comparing the numbers','比较数字前先对齐层次')+'</div></aside>'
    body='<section class="hero"><div class="wrap hero-grid"><div><span class="eyebrow">GM / SM / CRYPTOGRAPHIC ENGINEERING</span><h1>'+t('Read the algorithms<br><em>Inspect every layer</em>','读懂国密算法<br><em>看清每个层次</em>')+'</h1><p>'+t('An independent engineering atlas: SM1/2/3/4/7/9 and ZUC, with deep SM2 / NIST ECC, SM3 / SHA-2 / SHA-3 and SM4 / AES comparisons. Exact formulas, representations, original diagrams and runnable local reference code.','面向工程师的独立学习地图：SM1/2/3/4/7/9 与 ZUC，重点深入 SM2 / NIST ECC、SM3 / SHA-2 / SHA-3、SM4 / AES 对比，配有精确公式、编码说明、原创图解和可运行本地参考代码。')+'</p><div class="hero-actions"><a class="button" href="'+href('map',lang)+'">'+t('Explore the algorithm map →','从算法全景开始 →')+'</a><a class="text-link" href="'+href('labs',lang)+'">'+t('Inspect the round traces ↗','查看逐轮轨迹 ↗')+'</a></div><div class="hero-meta">21 SECTIONS / 17 DIAGRAMS / 3 LOCAL LABS<br>'+t('ENGLISH & 中文 · EXACT COMPARISONS · PRIMARY SOURCES','中英双语 · 精确对比 · 一手来源')+'</div></div>'+graphic+'</div></section><div class="reading wrap">'
    routes=[('01',t('Map the family and standards','整理算法族与标准'),t('Algorithm map → Standards → ECC foundations. Separate primitive, construction, protocol and product assurance.','算法全景 → 标准 → ECC 基础。区分原语、构造、协议与产品保障。')),('02',t('Follow the three SM2 operations','跟踪 SM2 的三种操作'),t('Signature → Encryption → Exchange → NIST ECC comparison. Track ZA, mod p versus mod n, nonce use and encoding.','签名 → 加密 → 密钥交换 → NIST ECC 对比。跟踪 ZA、mod p / mod n、Nonce 使用与编码。')),('03',t('Inspect hash and cipher internals','观察杂凑与分组密码内部'),t('SM3 → SHA-2 / SHA-3 → SM4 → AES → Modes. Read expansion, state updates, feed-forward and authentication.','SM3 → SHA-2 / SHA-3 → SM4 → AES → 模式。阅读扩展、状态更新、前馈和认证。')),('04',t('Connect code to engineering evidence','将代码连接到工程证据'),t('SM9 / ZUC → Protocols → Engineering → Practice / Labs. Run known answers, independent-library checks and rejection cases.','SM9 / ZUC → 协议 → 工程 → 实践 / 实验。运行已知答案、独立库检查和拒绝用例。'))]
    body+=section('01 / LEARNING ROUTE',t('From the standard to the actual bytes','从标准到实际字节'),t('Assumes basic cryptography/programming familiarity. Comparison chapters can also be read independently.','假设熟悉基本密码学和编程；对比章节也可独立阅读。'),'<div class="sequence">'+''.join(f'<article><span>{n}</span><div><h3>{title}</h3><p>{desc}</p></div></article>' for n,title,desc in routes)+'</div>','route')
    grid='<div class="topic-grid">'+''.join(f'<a class="topic-card" href="{href(page,lang)}"><span class="eyebrow">{i:02} / FIELD NOTES</span><h3>{NAV[lang][i]}</h3><p>{desc[1 if lang=="zh" else 0]}</p></a>' for i,(page,desc) in enumerate(zip(PAGES[1:],DESCRIPTIONS),1))+'</div>'
    body+=section('02 / CHAPTERS',t('Choose a mechanism or comparison','选择机制或对比'),t('Every direction stands on its own; tables and equations align the layers being compared.','每个方向独立展开，表格及等式对齐被比较的层次。'),grid,'chapters')
    body+=section('03 / PRACTICE',t('Three browser labs and a readable reference project','三个浏览器实验与可读参考项目'),t('Synthetic inputs, original code and independently checked outputs.','合成输入、原创代码与独立检查的输出。'),cards([('HASH',t('SM3 / SHA-256 / SHA3-256','SM3 / SHA-256 / SHA3-256'),t('Compute all three and inspect SM3 padding and 64-round compression.','计算三种摘要并观察 SM3 填充与 64 轮压缩。')),('BLOCK',t('SM4 / AES-128','SM4 / AES-128'),t('Use the same public key bytes and block, then inspect both round traces.','使用相同公开密钥字节和分组，观察两种逐轮轨迹。')),('CURVE',t('SM2 / P-256','SM2 / P-256'),t('Compute G, 2G or nG on exact domains; no key entry or signing.','在精确域上计算 G、2G 或 nG，无密钥输入或签名。')),('REFERENCE',t('Python + optional OpenSSL','Python + 可选 OpenSSL'),t('SM2 signatures/encryption/exchange, SM3, SM4 and AES-128 with known-answer and rejection tests.','SM2 签名 / 加密 / 交换、SM3、SM4、AES-128，含已知答案及拒绝测试。'))]),'practice')
    body+=callout(t('Inspect algorithms with their scope','按范围观察算法'),t('Reviewed 1 Oct 2026. SM1/7 disclosure limits and expired drafts are explicit. Reference/browser code is not constant-time or a certified product. Use synthetic examples only; the labs do not upload or store inputs.','复核于 2026 年 10 月 1 日。明确 SM1/7 公开边界和过期草案状态。参考 / 浏览器代码无恒定时间保证，也不是认证产品。仅使用合成例子；实验不上传或保存输入。'))
    return body+'</div>'

def chapter_page(page,lang):
    t=lambda en,zh:pick(lang,en,zh);rows=chapter(page,lang);idx=PAGES.index(page)
    body=hero(lang,page,NAV[lang][idx]+'<br><em>'+t('Mechanism and implementation','机制与实现')+'</em>',DESCRIPTIONS[idx-1][1 if lang=='zh' else 0],[(r[0],r[1]) for r in rows])+'<div class="reading wrap">'
    for i,(ident,title,intro,content,refs,viz) in enumerate(rows,1):body+=section(f'{i:02} / FIELD NOTES',title,intro,(diagram(viz,lang) if viz else '')+content+(cite(lang,*refs) if refs else ''),ident)
    body+=callout(t('Check your understanding','检查理解'),t('Name the inputs, output, modular domain, byte representation and acceptance/rejection checks. Explain which layer a proposed substitution would change.','指出输入、输出、模运算域、字节表示及接受 / 拒绝检查，解释所提替换会改变哪一层。'))
    return body+'</div>'

def labs_page(lang):
    t=lambda en,zh:pick(lang,en,zh)
    body=hero(lang,'labs',t('Inspect the intermediate state<br><em>Compare exact outputs</em>','观察中间状态<br><em>对比精确输出</em>'),t('Actual local teaching implementations, not production cryptography. No network request, secret-key entry, upload or stored experiment data. Use synthetic public examples.','实际本地教学实现，不是生产密码服务。无网络请求、秘密密钥输入、上传或实验数据保存；请使用合成公开例子。'),[('hash',t('Hash traces','杂凑轨迹')),('block',t('Block-cipher traces','分组密码轨迹')),('curve',t('Curve inspection','曲线检查'))])+'<div class="reading wrap"><noscript><aside class="callout">'+t('Enable JavaScript for experiments; lesson text and downloads remain available.','实验需要 JavaScript；正文及下载仍可使用。')+'</aside></noscript>'
    def select(ident,label,options):return f'<div class="lab-field"><label for="{ident}">{label}</label><select id="{ident}">'+''.join(f'<option value="{v}">{text}</option>' for v,text in options)+'</select></div>'
    def box(ident,controls,label):return f'<div class="lab-box"><div class="scenario-options">{controls}</div><div class="lab-actions"><button type="button" data-action="{ident}">{label}</button></div><p class="lab-state" data-pass="info" id="{ident}-state" role="status" aria-live="polite">'+t('Ready — choose public teaching inputs','就绪 — 选择公开教学输入')+f'</p><pre class="lab-output" id="{ident}-output"></pre></div>'
    controls='<label class="lab-field" for="hash-message">'+t('Synthetic message · UTF-8','合成消息 · UTF-8')+'<textarea id="hash-message" maxlength="2048" rows="3">abc</textarea></label>'
    body+=section('01 / HASH',t('Same bytes, three different 256-bit digests','相同字节，三种不同 256 位摘要'),t('SM3 and SHA3-256 use the original local core; SHA-256 uses Web Crypto. Input limit: 2048 encoded UTF-8 bytes.','SM3 与 SHA3-256 使用原创本地核心，SHA-256 使用 Web Crypto；输入上限为编码后 2048 个 UTF-8 字节。'),box('hash',controls,t('Compare the three hashes','比较三种杂凑'))+para(t('Try empty text, abc, 55 and 56 ASCII bytes, then Chinese text. The output shows SM3 A/E registers after each round. Different digests or avalanche behavior do not prove one algorithm is more secure. SHA3-256 is standardized SHA-3, not original Keccak-256.','尝试空文本、abc、55 / 56 个 ASCII 字节及中文。输出显示每轮之后的 SM3 A/E 寄存器。摘要不同或雪崩现象不证明某算法更安全。这里 SHA3-256 为标准 SHA-3，不是原始 Keccak-256。'))+cite(lang,'sm3-draft','sha2','sha3'),'hash')
    controls=select('block-key',t('Public test key','公开测试密钥'),[('standard','0123456789abcdeffedcba9876543210'),('aes','000102030405060708090a0b0c0d0e0f'),('zero','00000000000000000000000000000000')])+'<label class="lab-field" for="block-message">'+t('Synthetic plaintext block · 32 hexadecimal digits','合成明文分组 · 32 个十六进制数字')+'<input id="block-message" maxlength="32" value="0123456789abcdeffedcba9876543210" spellcheck="false"></label>'
    body+=section('02 / BLOCK',t('Observe one block under SM4 and AES-128','观察一个分组的 SM4 与 AES-128 运算'),t('Identical key bytes and plaintext are supplied to two different primitives. There is no mode, padding or authentication.','相同密钥字节和明文输入两种不同原语；没有模式、填充或认证。'),box('block',controls,t('Inspect both block cores','观察两个分组核心'))+para(t('The first preset with the default block produces the published SM4 answer 681edf34…536e4246. To reproduce the AES FIPS example, choose the second key and enter 00112233445566778899aabbccddeeff; AES gives 69c4e0d8…70b4c55a. SM4 inverse uses reversed round keys. Round count and trace length are not comparative security scores.','第一预设和默认分组产生公开 SM4 答案 681edf34…536e4246。复现 AES FIPS 例子时选第二密钥、输入 00112233445566778899aabbccddeeff，AES 得 69c4e0d8…70b4c55a。SM4 逆运算使用反序轮密钥。轮数及轨迹长度不是安全评分。'))+cite(lang,'sm4-draft','aes'),'block')
    controls=select('curve-domain',t('Exact domain','精确域'),[('sm2','curveSM2'),('p256','NIST P-256 / secp256r1')])+select('curve-scalar',t('Public scalar example','公开标量示例'),[('one','G (k=1)'),('two','2G (k=2)'),('order','nG (k=n)')])
    body+=section('03 / CURVE',t('The domain determines the point','域决定点'),t('Only predetermined public scalars are available. This does not generate a private key or a signature.','仅提供预定公开标量，不生成私钥或签名。'),box('curve',controls,t('Inspect the public point','检查公开点'))+para(t('Compare 2G on both curves, then nG. Both generators have order n and give infinity, but their coordinates and parameters differ. The implementation uses exact BigInt arithmetic and a readable variable-time affine formula. It is not a production ECC engine.','比较两条曲线的 2G，再计算 nG。两个基点阶均为 n，结果均为无穷远，但坐标及参数不同。实现使用精确 BigInt 与易读的变时仿射公式，不是生产 ECC 引擎。'))+cite(lang,'nist-curves','tls-sm'),'curve')
    return body+'</div>'

def bundle():
    required=['README.md','reference.py','test_reference.py','demo.py']
    with zipfile.ZipFile(ROOT/'examples.zip','w',compression=zipfile.ZIP_DEFLATED) as z:
        for n in required:
            info=zipfile.ZipInfo('gm-sm-atlas-examples/'+n,(2026,10,1,0,0,0));info.compress_type=zipfile.ZIP_DEFLATED;info.external_attr=0o100644<<16;z.writestr(info,(ROOT/'examples'/n).read_bytes())
if __name__=='__main__':
    bundle()
    for lang in ('en','zh'):
        for page in PAGES:
            body=overview(lang) if page=='index' else tools_page(lang) if page=='tools' else sources_page(lang) if page=='sources' else labs_page(lang) if page=='labs' else chapter_page(page,lang)
            (ROOT/href(page,lang)).write_text(shell(lang,page,body),encoding='utf-8')
    print(f'Built {2*len(PAGES)} pages / 17 diagrams / 3 labs / {len(TOOLS)} primary resources')
